from typing import List

def numberOfEnclaves(grid: List[List[int]]) -> int:
    if not grid or not grid[0]:
        return 0

    n, m = len(grid), len(grid[0])
    visited = [[False for _ in range(m)] for _ in range(n)]

    def is_boundary(i, j):
        return i == 0 or j == 0 or i == n - 1 or j == m - 1

    def dfs(i, j):
        if i < 0 or i >= n or j < 0 or j >= m or grid[i][j] == 0 or visited[i][j]:
            return
        visited[i][j] = True
        dfs(i + 1, j)
        dfs(i - 1, j)
        dfs(i, j + 1)
        dfs(i, j - 1)

    for i in range(n):
        for j in range(m):
            if (i == 0 or i == n - 1 or j == 0 or j == m - 1) and grid[i][j] == 1:
                dfs(i, j)

    count = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 1 and not visited[i][j]:
                count += 1
    return count
